//! Conversion between the JSON widget tree produced by the Bun runtime and
//! ewwii's `WidgetNode` AST.
//!
//! The JS side is intentionally very similar to `jscore.ewwii`'s widget API.
//! The extra `dyn_id` property (auto-generated by `runtime/widgets.js`) gives
//! every widget a stable identity in ewwii's widget registry across rebuilds.

use ewwii_plugin_api::shared_utils::ast::WidgetNode;
use ewwii_plugin_api::shared_utils::prop::{Property, PropertyMap};
use serde::Deserialize;
use serde_json::{Map, Value};

#[derive(Deserialize)]
struct WidgetData {
    #[serde(rename = "type")]
    widget_type: String,
    #[serde(default)]
    props: Map<String, Value>,
    #[serde(default)]
    children: Vec<WidgetData>,
}

/// Convert a single window JSON object into a `WidgetNode`.
pub fn convert_window(value: &Value) -> Result<WidgetNode, String> {
    let window: WidgetData = serde_json::from_value(value.clone())
        .map_err(|err| format!("Invalid window tree from Bun runtime: {err}"))?;
    to_node(window)
}

/// Convert the runtime's `tree` array (a list of window definitions) into an
/// ewwii widget tree.
pub fn convert_tree(value: &Value) -> Result<WidgetNode, String> {
    let windows: Vec<WidgetData> = serde_json::from_value(value.clone())
        .map_err(|err| format!("Invalid widget tree from Bun runtime: {err}"))?;

    let mut nodes = Vec::with_capacity(windows.len());
    for window in windows {
        nodes.push(to_node(window)?);
    }

    Ok(WidgetNode::Tree(nodes))
}

fn to_node(data: WidgetData) -> Result<WidgetNode, String> {
    let WidgetData {
        widget_type,
        props,
        children,
    } = data;

    let mut props_map = PropertyMap::new();
    for (key, value) in props {
        props_map.insert(key, map_json_value_to_property(value));
    }

    let children_nodes =
        || -> Result<Vec<WidgetNode>, String> { children.into_iter().map(to_node).collect() };

    let node = match widget_type.as_str() {
        "Label" => WidgetNode::Label { props: props_map },
        "Box" => WidgetNode::Box {
            props: props_map,
            children: children_nodes()?,
        },
        "FlowBox" => WidgetNode::FlowBox {
            props: props_map,
            children: children_nodes()?,
        },
        "Button" => WidgetNode::Button { props: props_map },
        "Image" => WidgetNode::Image { props: props_map },
        "Input" => WidgetNode::Input { props: props_map },
        "Progress" => WidgetNode::Progress { props: props_map },
        "ComboBoxText" => WidgetNode::ComboBoxText { props: props_map },
        "Scale" => WidgetNode::Scale { props: props_map },
        "Checkbox" => WidgetNode::Checkbox { props: props_map },
        "Expander" => WidgetNode::Expander {
            props: props_map,
            children: children_nodes()?,
        },
        "Revealer" => WidgetNode::Revealer {
            props: props_map,
            children: children_nodes()?,
        },
        "Scroll" => WidgetNode::Scroll {
            props: props_map,
            children: children_nodes()?,
        },
        "OverLay" => WidgetNode::OverLay {
            props: props_map,
            children: children_nodes()?,
        },
        "Stack" => WidgetNode::Stack {
            props: props_map,
            children: children_nodes()?,
        },
        "AspectFrame" => WidgetNode::AspectFrame {
            props: props_map,
            children: children_nodes()?,
        },
        "Calendar" => WidgetNode::Calendar { props: props_map },
        "ColorButton" => WidgetNode::ColorButton { props: props_map },
        "ColorChooser" => WidgetNode::ColorChooser { props: props_map },
        "CircularProgress" => WidgetNode::CircularProgress { props: props_map },
        "Graph" => WidgetNode::Graph { props: props_map },
        "Transform" => WidgetNode::Transform { props: props_map },
        "EventBox" => WidgetNode::EventBox {
            props: props_map,
            children: children_nodes()?,
        },
        "ToolTip" => WidgetNode::ToolTip {
            props: props_map,
            children: children_nodes()?,
        },
        "Animation" => WidgetNode::Animation {
            props: props_map,
            children: children_nodes()?,
        },
        "Custom" => WidgetNode::Custom {
            props: props_map,
            children: children_nodes()?,
        },

        "GtkUI" => WidgetNode::GtkUI { props: props_map },
        "Script" => WidgetNode::Script { props: props_map },

        "Window" => {
            let name = match props_map.get("name") {
                Some(Property::String(name)) => name.clone(),
                _ => return Err("Window widgets require a string `name` property".into()),
            };

            let mut children = children_nodes()?;
            let node = if children.is_empty() {
                // Keep ewwii from panicking on an empty window. This is almost
                // always a user mistake, so make it visible in the log too.
                eprintln!("bun-ewwii: warning: window '{name}' has no children");
                WidgetNode::Label {
                    props: PropertyMap::default(),
                }
            } else {
                children.remove(0)
            };

            WidgetNode::DefWindow {
                name,
                props: props_map,
                node: Box::new(node),
            }
        }
        "Poll" => {
            let var = match props_map.get("var") {
                Some(Property::String(var)) => var.clone(),
                _ => return Err("Poll widgets require a string `var` property".into()),
            };
            WidgetNode::Poll {
                var,
                props: props_map,
            }
        }
        "Listen" => {
            let var = match props_map.get("var") {
                Some(Property::String(var)) => var.clone(),
                _ => return Err("Listen widgets require a string `var` property".into()),
            };
            WidgetNode::Listen {
                var,
                props: props_map,
            }
        }

        other => {
            eprintln!("bun-ewwii: warning: unknown widget type '{other}', rendering a Label");
            WidgetNode::Label { props: props_map }
        }
    };

    Ok(node)
}

fn map_json_value_to_property(value: Value) -> Property {
    match value {
        Value::Null => Property::from(""),
        Value::Bool(value) => Property::from(value),
        Value::Number(number) => {
            if let Some(value) = number.as_i64() {
                Property::from(value)
            } else if let Some(value) = number.as_f64() {
                Property::from(value)
            } else {
                Property::from(number.to_string())
            }
        }
        Value::String(value) => Property::from(value),
        Value::Array(values) => Property::from(
            values
                .into_iter()
                .map(map_json_value_to_property)
                .collect::<Vec<_>>(),
        ),
        Value::Object(values) => {
            let mut map = PropertyMap::default();
            for (key, value) in values {
                map.insert(key, map_json_value_to_property(value));
            }
            Property::from(map)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn converts_window_tree() {
        let tree = json!([
            {
                "type": "Window",
                "props": { "name": "bar", "dyn_id": "w1" },
                "children": [
                    {
                        "type": "Box",
                        "props": { "widget_name": "root", "dyn_id": "b1" },
                        "children": [
                            { "type": "Label", "props": { "text": "hi", "dyn_id": "l1" } }
                        ]
                    }
                ]
            }
        ]);

        let node = convert_tree(&tree).expect("tree should convert");
        match node {
            WidgetNode::Tree(windows) => {
                assert_eq!(windows.len(), 1);
                assert!(matches!(windows[0], WidgetNode::DefWindow { .. }));
            }
            _ => panic!("expected a tree"),
        }
    }

    #[test]
    fn rejects_window_without_name() {
        let tree = json!([{ "type": "Window", "props": {}, "children": [] }]);
        assert!(convert_tree(&tree).is_err());
    }
}
